const items = $input.all();
return items.map((item) => {
  const fromRaw = item.json.from;
  let emailAddress = '';
  if (fromRaw && typeof fromRaw === 'object' && fromRaw.value && fromRaw.value[0]) {
    emailAddress = fromRaw.value[0].address || '';
  } else if (typeof fromRaw === 'string') {
    emailAddress = fromRaw;
  }
  emailAddress = emailAddress.trim().toLowerCase();

  const atIndex = emailAddress.lastIndexOf('@');
  const domaine = atIndex > -1 && atIndex < emailAddress.length - 1
    ? emailAddress.slice(atIndex + 1)
    : 'inconnu';

  return {
    json: {
      expediteur: emailAddress || 'inconnu@inconnu.local',
      domaine,
      sujet: item.json.subject || '(sans sujet)',
      date: item.json.date || new Date().toISOString(),
      corps: item.json.textPlain || item.json.text || '',
      messageId: item.json.messageId || item.json['message-id'] || '',
    },
  };
});

const searchResults = $input.all();
const emailData = $('Extraire Champs Email').first().json;

if (searchResults.length > 0 && searchResults[0].json.id) {
  return [{
    json: {
      clientId: searchResults[0].json.id,
      isNew: false,
      domaine: emailData.domaine,
    },
  }];
}

return [{
  json: {
    clientId: null,
    isNew: true,
    domaine: emailData.domaine,
  },
}];

const emailData = $('Extraire Champs Email').first().json;
return [{
  json: {
    'Nom': emailData.domaine,
    'Domaine email': emailData.domaine,
    'Date création': new Date().toISOString(),
  },
}];

const created = $input.first().json;
const emailData = $('Extraire Champs Email').first().json;
return [{
  json: {
    clientId: created.id,
    domaine: emailData.domaine,
  },
}];

const clientInfo = $input.first().json;
const emailData = $('Extraire Champs Email').first().json;

return [{
  json: {
    'Sujet': emailData.sujet,
    'Expéditeur': emailData.expediteur,
    'Date': emailData.date,
    'Corps': emailData.corps,
    'Message-ID': emailData.messageId,
    'Statut traitement': 'Nouveau',
    'Client': [clientInfo.clientId],
  },
}];

// Un item en entrée (la fiche Mail créée) -> N items en sortie (un par PJ).
// Si l'email n'a pas de PJ, binary est vide et aucun item n'est renvoyé :
// toute la branche s'arrête naturellement ici (cas N=0 géré sans IF).
const mailRecord = $input.first().json;
const emailData = $('Extraire Champs Email').first().json;
const original = $('IMAP - Nouveau Mail').first();
const binary = original.binary || {};

return Object.keys(binary).map((key) => {
  const bin = binary[key];
  return {
    json: {
      mailId: mailRecord.id,
      domaine: emailData.domaine,
      fileName: bin.fileName || key,
      mimeType: bin.mimeType || 'application/octet-stream',
      fileSize: bin.fileSize ? Number(bin.fileSize) : 0,
    },
    binary: { data: bin },
  };
});

const searchItem = $input.item;
const ctx = $('Extraire Pièces Jointes').item;
const found = searchItem.json && searchItem.json.id;

return {
  json: {
    ...ctx.json,
    folderExists: !!found,
    folderId: found ? searchItem.json.id : null,
  },
  binary: ctx.binary,
};

const created = $input.item.json;
const ctx = $('Normaliser Résultat Dossier').item;

return {
  json: {
    ...ctx.json,
    folderId: created.id,
  },
  binary: ctx.binary,
};

const uploaded = $input.item.json;
const att = $('Extraire Pièces Jointes').item.json;

return {
  json: {
    'Nom du fichier': att.fileName,
    'Type MIME': att.mimeType,
    'Taille (octets)': att.fileSize,
    'URL cloud': uploaded.webViewLink || uploaded.webContentLink || '',
    "Date d'arrivée": new Date().toISOString(),
    'Statut upload': 'Uploadé',
    'Erreur': '',
    'Mail': [att.mailId],
  },
};

const erreur = $input.item.json;
const att = $('Extraire Pièces Jointes').item.json;

return {
  json: {
    'Nom du fichier': att.fileName,
    'Type MIME': att.mimeType,
    'Taille (octets)': att.fileSize,
    'URL cloud': '',
    "Date d'arrivée": new Date().toISOString(),
    'Statut upload': 'Échec',
    'Erreur': (erreur.error && erreur.error.message) || erreur.message || 'Échec upload cloud (raison inconnue)',
    'Mail': [att.mailId],
  },
};
